8	// Full idle/resume cycle over sliding windows (window 1000, slide 600, two
9	// partitions): declaring a partition idle only removes it from the effective
10	// watermark, events both partitions contributed before the idle declaration
11	// stay in their still-open windows, and after resuming, the partition keeps
12	// feeding the overlapping windows it shares with the others.
13	func TestAggregateSlidingIdleResumeFullCycle(t *testing.T) {
14		input := strings.Join([]string{
15			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
16			`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
17			`{"type":"watermark","time":1000,"partition":0}`,
18			`{"type":"watermark","time":600,"partition":1}`,                  // effective = 600: nothing closes
19			`{"type":"idle","partition":1}`,                                  // effective = 1000: closes only [0,1000)
20			`{"type":"watermark","time":1000,"partition":1}`,                 // resume at the effective watermark: no re-emit
21			`{"type":"event","key":"k","time":1000,"value":4,"partition":1}`, // joins the still-open [600,1600)
22			`{"type":"watermark","time":1600,"partition":0}`,                 // min stays 1000: [600,1600) still open
23			`{"type":"watermark","time":1600,"partition":1}`,                 // min = 1600: closes [600,1600)
24		}, "\n")
25		stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
26		if err != nil {
27			t.Fatalf("unexpected error: %v", err)
28		}
29		if stderr != "" {
30			t.Fatalf("unexpected stderr: %q", stderr)
31		}
32		want := strings.Join([]string{
33			// Only partition 0's event at 700 falls in [0,1000); the events at
34			// 1000 belong to the next window and must not leak back.
35			`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
36			// Pre-idle contributions (2 from p0, 3 from p1) survive the idle
37			// period and merge with the post-resume event (4 from p1).
38			`{"key":"k","start":600,"end":1600,"count":3,"sum":9}`,
39			``,
40		}, "\n")
41		if stdout != want {
42			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
43		}
44	}
45	
46	// Resume validation with sliding windows: a resume watermark below the
47	// partition's own pre-idle watermark, or at/above it but below the current
48	// effective watermark, is fatal with the physical line number (blank lines
49	// count) and a reason naming the violated bound. Output produced before the
50	// error is retained and records after the failing line produce nothing.
51	func TestAggregateSlidingIdleResumeErrors(t *testing.T) {
52		prefix := []string{
53			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
54			``, // blank physical line: skipped but counted in line numbers
55			`{"type":"watermark","time":1000,"partition":0}`,
56			`{"type":"watermark","time":600,"partition":1}`,
57			`{"type":"idle","partition":1}`, // line 5: effective = 1000, closes [0,1000)
58		}
59		closed := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
60	
61		cases := []struct {
62			name      string
63			resume    string
64			wantInMsg []string
65		}{
66			{
67				"below own previous watermark",
68				`{"type":"watermark","time":500,"partition":1}`, // < p1's pre-idle 600
69				[]string{"partition 1", "previous watermark", "600"},
70			},
71			{
72				"above own previous but below effective",
73				`{"type":"watermark","time":800,"partition":1}`, // >= 600 own, < 1000 effective
74				[]string{"partition 1", "effective watermark", "1000"},
75			},
76		}
77		for _, tc := range cases {
78			t.Run(tc.name, func(t *testing.T) {
79				lines := append(append([]string{}, prefix...), tc.resume)
80				// A record after the failing line that would close [600,1600)
81				// if it were ever processed.
82				lines = append(lines, `{"type":"watermark","time":5000,"partition":0}`)
83				stdout, _, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
84				if err == nil {
85					t.Fatal("expected resume error, got nil")
86				}
87				inputErr, ok := err.(*InputError)
88				if !ok {
89					t.Fatalf("expected *InputError, got %T: %v", err, err)
90				}
91				if inputErr.Line != 6 {
92					t.Errorf("line = %d, want 6 (blank line 2 counts)", inputErr.Line)
93				}
94				for _, sub := range tc.wantInMsg {
95					if !strings.Contains(inputErr.Reason, sub) {
96						t.Errorf("reason = %q, want substring %q", inputErr.Reason, sub)
97					}
98				}
99				if stdout != closed {
100					t.Fatalf("output before the error must be retained and nothing after it emitted, got %q want %q", stdout, closed)
101				}
102			})
103		}
104	}
105	
106	// After a successful resume the effective watermark still governs lateness:
107	// an event below it is reported late and skipped even though it falls inside
108	// the still-open overlapping window, while an event exactly at the watermark
109	// is counted normally.
110	func TestAggregateSlidingResumeLateEventRules(t *testing.T) {
111		input := strings.Join([]string{
112			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
113			`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
