117			`{"type":"watermark","time":1000,"partition":1}`,                 // resume at the boundary
118			`{"type":"event","key":"k","time":999,"value":1,"partition":1}`,  // late vs 1000 despite open [600,1600)
119			`{"type":"event","key":"k","time":1000,"value":4,"partition":1}`, // exactly at the watermark: counted
120			`{"type":"watermark","time":1600,"partition":0}`,
