	}

	for _, sl := range []int64{0, -1, 1001} {
		if err := RunAggregatePartitionedSliding(strings.NewReader(""), 1000, sl, 2, &bytes.Buffer{}, &bytes.Buffer{}); err == nil {
			t.Fatalf("expected error for slide %d", sl)
		}
	}
}

